<template><div><PageHeader title="员工档案" description="管理员工入职、档案变更和离职"><el-button :icon="Download" @click="download">导出 Excel</el-button><el-button type="primary" :icon="Plus" @click="openCreate">新建员工</el-button></PageHeader><section class="filter-band"><el-select v-model="filters.department_id" clearable placeholder="全部部门" @change="search"><el-option v-for="d in flatDepartments" :key="d.id" :label="d.name" :value="d.id" /></el-select><el-select v-model="filters.status" clearable placeholder="全部状态" @change="search"><el-option label="在职" value="ACTIVE"/><el-option label="离职" value="RESIGNED"/></el-select><el-input v-model="filters.keyword" clearable placeholder="姓名 / 工号 / 手机号" @keyup.enter="search"><template #append><el-button :icon="Search" @click="search" /></template></el-input></section><section class="panel table-panel"><el-table v-loading="loading" :data="rows"><el-table-column prop="employee_no" label="工号" width="150"/><el-table-column prop="name" label="姓名" width="110"/><el-table-column prop="phone" label="手机号" width="150"/><el-table-column prop="id_card" label="身份证号" min-width="190"/><el-table-column prop="department_id" label="部门 ID" width="100"/><el-table-column prop="position_id" label="岗位 ID" width="100"/><el-table-column prop="hire_date" label="入职日期" width="120"/><el-table-column prop="status" label="状态" width="90"><template #default="{row}"><el-tag :type="row.status==='ACTIVE'?'success':'info'">{{row.status==='ACTIVE'?'在职':'离职'}}</el-tag></template></el-table-column><el-table-column label="操作" width="180" fixed="right"><template #default="{row}"><el-button link type="primary" @click="openEdit(row)">编辑</el-button><el-button v-if="row.status==='ACTIVE'" link type="danger" @click="resign(row)">办理离职</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="filters.page" v-model:page-size="filters.page_size" :total="total" layout="total, prev, pager, next" @current-change="load" /></section><el-dialog v-model="visible" :title="editing?'编辑员工':'新建员工'" width="680"><el-form :model="form" label-position="top" class="form-grid"><el-form-item label="姓名" required><el-input v-model="form.name"/></el-form-item><el-form-item label="性别"><el-select v-model="form.gender"><el-option label="男" value="男"/><el-option label="女" value="女"/></el-select></el-form-item><el-form-item label="手机号" required><el-input v-model="form.phone"/></el-form-item><el-form-item label="邮箱"><el-input v-model="form.email"/></el-form-item><el-form-item label="身份证号"><el-input v-model="form.id_card"/></el-form-item><el-form-item label="入职日期" required><el-date-picker v-model="form.hire_date" value-format="YYYY-MM-DD" style="width:100%"/></el-form-item><el-form-item label="部门" required><el-select v-model="form.department_id"><el-option v-for="d in flatDepartments" :key="d.id" :label="d.name" :value="d.id"/></el-select></el-form-item><el-form-item label="岗位" required><el-select v-model="form.position_id"><el-option v-for="p in positions" :key="p.id" :label="p.name" :value="p.id"/></el-select></el-form-item><el-form-item label="紧急联系人"><el-input v-model="form.emergency_contact"/></el-form-item><el-form-item label="紧急联系电话"><el-input v-model="form.emergency_phone"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog></div></template>
<script setup>
import{computed,onMounted,reactive,ref}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{Download,Plus,Search}from'@element-plus/icons-vue';import PageHeader from'../components/PageHeader.vue';import{departmentApi,employeeApi,positionApi}from'../api';const rows=ref([]),departments=ref([]),positions=ref([]),total=ref(0),loading=ref(false),visible=ref(false),saving=ref(false),editing=ref(null);const filters=reactive({department_id:null,status:null,keyword:'',page:1,page_size:20});const blank=()=>({name:'',gender:null,phone:'',email:null,id_card:null,department_id:null,position_id:null,hire_date:'',emergency_contact:null,emergency_phone:null});const form=reactive(blank());const flatDepartments=computed(()=>{const out=[];const walk=(list)=>list.forEach(x=>{out.push(x);walk(x.children||[])});walk(departments.value);return out});async function load(){loading.value=true;try{const r=await employeeApi.list(filters);rows.value=r.data.items;total.value=r.data.total}catch(e){ElMessage.error(e.businessMessage)}finally{loading.value=false}}async function bootstrap(){const[d,p]=await Promise.all([departmentApi.list(),positionApi.list()]);departments.value=d.data||[];positions.value=p.data||[];await load()}function search(){filters.page=1;load()}function openCreate(){editing.value=null;Object.assign(form,blank());visible.value=true}async function openEdit(row){editing.value=row;const r=await employeeApi.detail(row.id);Object.assign(form,r.data);visible.value=true}async function save(){if(!form.name||!form.phone||!form.department_id||!form.position_id||!form.hire_date)return ElMessage.warning('请填写必填项');saving.value=true;try{editing.value?await employeeApi.update(editing.value.id,form):await employeeApi.create(form);visible.value=false;ElMessage.success('保存成功');await load()}catch(e){ElMessage.error(e.businessMessage)}finally{saving.value=false}}async function resign(row){try{await ElMessageBox.confirm(`确认将 ${row.name} 办理离职？账号将同步停用。`,'办理离职',{type:'warning'});await employeeApi.resign(row.id);ElMessage.success('离职办理完成');await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e.businessMessage)}}async function download(){try{const blob=await employeeApi.export();const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='employees.xlsx';a.click();URL.revokeObjectURL(url)}catch(e){ElMessage.error(e.businessMessage)}}onMounted(()=>bootstrap().catch(e=>ElMessage.error(e.businessMessage)))
</script>
